from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from .models import StudentGrade
from .serializers import StudentGradeSerializer

class SortedRankList(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        if not request.user.is_staff:
            return Response({"error": "Unauthorized access shield triggered."}, status=403)
        queryset = StudentGrade.objects.all().order_by('-cgpa', 'student_id')
        serializer = StudentGradeSerializer(queryset, many=True)
        return Response(serializer.data)
